/* Skin "amber-minimal" (Amber Minimal): the tweakcn preset "amber-minimal" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="amber-minimal" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Inter (Google Fonts, loaded when the skin is on). */
[data-skin="amber-minimal"] {
  --background: hsl(0 0% 100%);
  --foreground: hsl(0 0% 15%);
  --card: hsl(0 0% 100%);
  --card-foreground: hsl(0 0% 15%);
  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(0 0% 15%);
  --primary: hsl(37.7 92.1% 50.2%);
  --primary-foreground: hsl(0 0% 0%);
  --secondary: hsl(220 14% 96%);
  --secondary-foreground: hsl(215 14% 34%);
  --muted: hsl(210 20% 98%);
  --muted-foreground: hsl(220 9% 46%);
  --accent: hsl(48 100% 96%);
  --accent-foreground: hsl(22.7 82.5% 31.4%);
  --destructive: hsl(358.3 71.8% 52.7%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(220 13% 91%);
  --input: hsl(220 13% 91%);
  --ring: hsl(37.7 92.1% 50.2%);
  --chart-1: hsl(37.7 92.1% 50.2%);
  --chart-2: hsl(32.1 94.6% 43.7%);
  --chart-3: hsl(26 90% 37%);
  --chart-4: hsl(22.7 82.5% 31.4%);
  --chart-5: hsl(21.7 77.8% 26.5%);
  --sidebar: hsl(210 20% 98%);
  --sidebar-foreground: hsl(0 0% 15%);
  --sidebar-primary: hsl(37.7 92.1% 50.2%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(48 100% 96%);
  --sidebar-accent-foreground: hsl(22.7 82.5% 31.4%);
  --sidebar-border: hsl(220 13% 91%);
  --sidebar-ring: hsl(37.7 92.1% 50.2%);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --radius: 0.375rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 1px 2px -2px hsl(0 0% 0% / 0.10);
  --shadow: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 1px 2px -2px hsl(0 0% 0% / 0.10);
  --shadow-md: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 2px 4px -2px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 4px 6px -2px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 8px 10px -2px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(358.3 71.8% 46.7%);
}

:is(.dark, [data-theme="dark"]) [data-skin="amber-minimal"],
[data-skin="amber-minimal"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(0 0% 9%);
  --foreground: hsl(0 0% 90%);
  --card: hsl(0 0% 15%);
  --card-foreground: hsl(0 0% 90%);
  --popover: hsl(0 0% 15%);
  --popover-foreground: hsl(0 0% 90%);
  --primary: hsl(37.7 92.1% 50.2%);
  --primary-foreground: hsl(0 0% 0%);
  --secondary: hsl(0 0% 15%);
  --secondary-foreground: hsl(0 0% 90%);
  --muted: hsl(0 0% 12%);
  --muted-foreground: hsl(0 0% 64%);
  --accent: hsl(22.7 82.5% 31.4%);
  --accent-foreground: hsl(48 96.6% 76.7%);
  --destructive: hsl(358.3 71.8% 52.7%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(0 0% 25%);
  --input: hsl(0 0% 25%);
  --ring: hsl(37.7 92.1% 50.2%);
  --chart-1: hsl(43.3 96.4% 56.3%);
  --chart-2: hsl(32.1 94.6% 43.7%);
  --chart-3: hsl(22.7 82.5% 31.4%);
  --chart-4: hsl(26 90% 37%);
  --chart-5: hsl(22.7 82.5% 31.4%);
  --sidebar: hsl(0 0% 6%);
  --sidebar-foreground: hsl(0 0% 90%);
  --sidebar-primary: hsl(37.7 92.1% 50.2%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(22.7 82.5% 31.4%);
  --sidebar-accent-foreground: hsl(48 96.6% 76.7%);
  --sidebar-border: hsl(0 0% 25%);
  --sidebar-ring: hsl(37.7 92.1% 50.2%);
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 1px 2px -2px hsl(0 0% 0% / 0.10);
  --shadow: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 1px 2px -2px hsl(0 0% 0% / 0.10);
  --shadow-md: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 2px 4px -2px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 4px 6px -2px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.10), 0px 8px 10px -2px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(358.3 71.8% 46.7%);
}

[data-skin="amber-minimal"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="amber-minimal"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="amber-minimal"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="amber-minimal"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="amber-minimal"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="amber-minimal"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
